"""人工核对的玩家说明；属性和贴图由 build.py 从源码读取。"""
CATEGORIES = {'guide':'流程攻略','boss':'首领图鉴','item':'道具图鉴','npc':'人物图鉴','enemy':'敌怪图鉴','place':'地区与建筑','mechanic':'机制百科'}
ENTRIES = []
def entry(id, title, category, summary, sections, related=(), source=(), image=None, stats=None, tag=None):
    ENTRIES.append(dict(id=id,title=title,category=category,summary=summary,sections=sections,related=list(related),source=list(source),image=image,stats=stats or {},tag=tag))
def item(id,title,path,summary,obtain,usage,related=(),recipe=None,stats=None,image=None,tag=None):
    sections={'获取方式':obtain,'使用与效果':usage}
    if recipe: sections['合成配方']=recipe
    entry(id,title,'item',summary,sections,related,['Content/Items/'+path],image,stats,tag)
WAVE='击败再不斩与白后，四种职业武器保底随机获得一把；另有 20% 概率额外获得一把不同的武器。专家模式通过宝藏袋领取同样的武器奖励。'
item('kubikiribocho','斩首大刀','Weapons/Kubikiribocho.cs','挥动沉重的近战巨刀，命中有机会恢复生命。',WAVE,'命中非无敌敌人时，20% 概率恢复 2 生命。可以自动连续挥动。',['wave-duo','zabuza','chakra'])
item('senbon','千本','Weapons/Senbon.cs','一次扇形投出三根千本，可反复使用。',WAVE,'每次投掷三根千本，不消耗物品。与写轮眼的看破效果有联动。',['wave-duo','haku','sharingan'])
item('water-dragon','水遁·水龙弹之术','Weapons/WaterDragonJutsu.cs','结印释放追向敌人的水龙，属于魔法武器。',WAVE,'消耗原版魔力，发射可追踪敌人的水龙。查克拉和魔力是不同的资源。',['wave-duo','chakra'])
item('ice-mirror','秘术·魔镜冰晶','Weapons/IceMirrorJutsu.cs','召唤冰镜，向敌人投出千本。',WAVE,'在鼠标位置召唤冰镜，每面占用一个召唤栏位。使用时消耗魔力。',['wave-duo','haku'])
item('kunai','训练苦无','TrainingKunai.cs','木叶下忍的基础远程忍具。','新角色获得的初始物品。','投掷后不消耗，可以连续使用。',['getting-started','sharingan'])
item('wraps','训练用绷带','Taijutsu/TaijutsuWeapon.cs','早期可制作的体术武器，每次出拳产生风压。','在工作台制作。','左键打出风压，右键施展木叶旋风。八门开启时，风压更大、射程更长。',['taijutsu','gates'],'任意木材 ×10 ＋ 丝绸 ×3 → 训练用绷带 ×1；工作台。',{'基础伤害':'14','使用时间':'15 帧','伤害类型':'体术','击退':'3'},'Content/Items/Taijutsu/TrainingWraps.png')
item('leg-weights','小李的负重护腿','Taijutsu/TaijutsuWeapon.cs','比训练绷带更强、更快的体术武器。','参与击败我爱罗的角色首次胜利必得；常规掉落规则另以 1/3 概率掉落。','左键风压、右键木叶旋风，右键冷却 1.5 秒。属于武器，不是装备后增加属性的饰品。',['gaara','taijutsu','gates'],stats={'基础伤害':'30','使用时间':'12 帧','伤害类型':'体术','击退':'4'},image='Content/Items/Taijutsu/LeeLegWeights.png')
item('sharingan','装在试管里的写轮眼（一勾玉）','StyleCores/TierOneCores.cs','写轮眼流派的第一阶核心，以饰品形式装备。','首次完成死亡森林大蛇丸遭遇获得，倒下时在复活后发放；用蛇蜕重战另有 25% 概率掉落。','木头自然恢复间隔由 20 秒缩短至 16 秒。V 键【看破】消耗 30 查克拉，冷却 20 秒，4 秒内受到第一次攻击时自动替身；成功后 3 秒伤害 +15%。苦无、千本命中被看破的敌人必定暴击。',['orochimaru','styles','substitution'],image='Content/Items/StyleCores/SharinganCore1.png')
item('gates','八门遁甲之卷','StyleCores/TierOneCores.cs','八门流派第一阶核心，可开启前三门。','参与击败我爱罗的角色首次胜利必得；常规掉落规则另以 25% 概率掉落。','体术攻速 +10%。每按 V 开一门，耗 20 查克拉；每门伤害、移动速度 +10%。一至三门每秒分别失去 2/4/6 生命。三门后再按关闭；生命低于 20% 强制关闭并进入 10 秒疲劳。',['gaara','styles','taijutsu'],image='Content/Items/StyleCores/EightGatesCore.png')
item('byakugan','白眼','StyleCores/TierOneCores.cs','白眼流派第一阶核心，提供点穴与回天。','宁次以 25% 概率掉落。','看见附近敌人，近战命中叠加点穴，每层防御 −4，最多三层；Boss 每层多受 5% 伤害。V 键【回天】消耗 40 查克拉，冷却 15 秒，持续 1 秒，抵消敌方弹幕并弹开近身敌人。',['neji','styles'],image='Content/Items/StyleCores/ByakuganCore.png')
item('pill','兵粮丸','ChakraPill.cs','应急补充查克拉的消耗品。','工作台制作；湖边水牢事件结束也会奖励 3 个。','立即恢复 40 查克拉，之后 10 秒不能再次服用。',['chakra','lake'],'蘑菇 ×1 ＋ 太阳花 ×1 → 兵粮丸 ×2；工作台。')
item('crystal','查克拉结晶','ChakraCrystal.cs','永久增加查克拉上限的消耗品。','地下探索获得；每个角色首次击败波之国双首领奖励一个。','每次使用增加 20 上限，初始 100，最多 200，共可使用 5 个。',['chakra','wave-duo'])
item('handbook','忍者手册','NinjaHandbook.cs','游戏内的任务与机制查询入口。','新角色初始获得；可找卡卡西补发，也可重新制作。','使用后打开手册，查询当前任务、忍术、查克拉与首领线索。',['kakashi','getting-started'],'木材 ×1 → 忍者手册 ×1；无需制作站。')
item('insignia','雾隐标记','MistInsignia.cs','制作再不斩挑战卷轴的材料。','鬼之兄弟每人必掉一个；听达兹纳坦白后补得一个。','集齐三枚后，配合木材制作挑战卷轴。',['demon-brothers','tazuna','wave-scroll'])
item('wave-scroll','再不斩的挑战卷轴','ZabuzaChallengeScroll.cs','在大桥附近召唤波之国双首领战，不消耗。','断桥雾中见过再不斩后，在工作台制作。','距离大桥不超过 70 格使用。先召唤再不斩，半血后白加入。场上有再不斩或白时无法再召唤。',['wave-duo','bridge'],'雾隐标记 ×3 ＋ 木材 ×10 → 挑战卷轴 ×1；工作台；需要完成断桥雾中的相遇。',image='Content/Items/MissionScroll.png')
item('recommendation','中忍考试推荐书','ExamAdmissionScroll.cs','波之国后进入中忍考试的凭证。','波之国尾声后由卡卡西交付；遗失可补发。','携带它到忍者学校，找伊比喜开始笔试。',['exam-guide','ibiki','kakashi'])
